func TestNRVEncoder_RunCollectsAllEntries(t *testing.T) {
	dir := t.TempDir()

	entries := []map[string]interface{}{
		{
			"id":    "doc1",
			"ready": true,
			"payload": map[string]interface{}{
				"arrow_path": filepath.Join(dir, "doc1.arrow"),
